    'm8.deeper.0.title': 'Qué aplica realmente un sandbox',
    'm8.deeper.1.title': 'Inyección de prompt: cuando la entrada del agente es el atacante',
    'm8.drill.title': 'Simulacro 8 · Reduce el radio de impacto',
    'm8.drill.intro': 'Credenciales, puertas, rollback y confianza calibrada. Cinco decisiones que deciden si un mal día es un encogimiento de hombros o una historia de guerra.',
    'm9.title': 'El Gauntlet · Proyecto final',
    'm9.tagline': 'Un día realista como steward. Todo de los módulos 1–8, a la vez, con consecuencias.',
    'm9.lessons.0.title': 'Briefing: un día en LedgerLoop',
    'm9.deeper.0.title': 'Construye tu propio laboratorio de steward',
    'm9.drill.title': 'El Gauntlet · Ocho puntos de control',
